values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'quick-links', 'Quick link cards', '{"items":[{"title":"Admissions","text":"Applications for the new year","icon":"graduation-cap","href":"/admissions"},{"title":"Academics","text":"Programs from Grade 6 to 12","icon":"book","href":"/academics"},{"title":"Campus life","text":"Clubs, sports and the arts","icon":"trophy","href":"/campus-life"},{"title":"Calendar","text":"Term dates and events","icon":"calendar","href":"/campus-life"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"items":{"minItems":2,"maxItems":4,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["graduation-cap","book","flask","calendar","trophy","palette","music","users","award","shield","landmark"]},"href":{"type":"string","maxLength":2048}},"required":["title","icon"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}'::jsonb, 110);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'welcome', 'Principal''s welcome', '{"eyebrow":"Welcome to Crestview","title":"Every student known, every talent nurtured","text":"For more than sixty years, Crestview has helped young people discover what they love and build the character to pursue it. Our teachers know each student by name, and our community celebrates every kind of success.","quote":"We do not just prepare students for exams. We prepare them for a life of learning, service and leadership.","name":"Dr. Margaret Hale","role":"Principal","image":{"src":"/themes/crestview/graduate.jpg","alt":"Principal at the graduation ceremony"},"button":{"label":"About our school","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"quote":{"type":"string","minLength":1,"maxLength":2000},"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","name","image"],"additionalProperties":false}'::jsonb, 120);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'programs', 'Program cards', '{"eyebrow":"Academics","title":"Programs that open doors","text":"A broad, rigorous curriculum with the support each student needs to thrive.","items":[{"title":"Middle School","tag":"Grades 6–8","text":"Strong foundations in literacy, numeracy and inquiry, with time to explore new interests.","image":{"src":"/themes/crestview/raised-hand.jpg","alt":"Student raising a hand in class"},"href":"/academics"},{"title":"High School","tag":"Grades 9–12","text":"Advanced courses, university counselling and leadership opportunities in every subject.","image":{"src":"/themes/crestview/reading-class.jpg","alt":"High school students reading in class"},"href":"/academics"},{"title":"Science & Technology","tag":"STEM","text":"Modern labs, robotics and coding clubs where students learn by building and testing.","image":{"src":"/themes/crestview/science-lab.jpg","alt":"Students in the science lab"},"href":"/academics"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":9,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"tag":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"href":{"type":"string","maxLength":2048}},"required":["title","image"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'news-events', 'News and events', '{"eyebrow":"What''s happening","title":"News and events","news":[{"title":"Class of 2026 celebrates a record year of university offers","date":"18 Jun 2026","image":{"src":"/themes/crestview/graduation.jpg","alt":"Graduates throwing their caps"},"href":"/campus-life"},{"title":"New library learning commons opens to students","date":"2 May 2026","image":{"src":"/themes/crestview/library.jpg","alt":"The new library"},"href":"/campus-life"},{"title":"Crestview wins the regional science fair","date":"21 Apr 2026","image":{"src":"/themes/crestview/writing.jpg","alt":"Student working on a project"},"href":"/campus-life"}],"eventsTitle":"Upcoming events","events":[{"day":"14","month":"Nov","title":"Admissions open house","time":"10:00 AM – 1:00 PM","place":"Main hall"},{"day":"22","month":"Nov","title":"Annual sports day","time":"8:30 AM onwards","place":"Crestview fields"},{"day":"05","month":"Dec","title":"Winter concert","time":"6:00 PM","place":"Auditorium"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"news":{"maxItems":3,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"date":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"href":{"type":"string","maxLength":2048}},"required":["title","date","image"],"additionalProperties":false}},"eventsTitle":{"type":"string","minLength":1,"maxLength":200},"events":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"day":{"type":"string","minLength":1,"maxLength":200},"month":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"time":{"type":"string","minLength":1,"maxLength":200},"place":{"type":"string","minLength":1,"maxLength":200}},"required":["day","month","title"],"additionalProperties":false}}},"required":["title","news","events"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'steps', 'Numbered steps', '{"eyebrow":"How to apply","title":"Four simple steps","text":"Our admissions team will guide you at every stage.","items":[{"title":"Enquire","text":"Send us your details and we will share the prospectus."},{"title":"Visit","text":"Tour the campus and meet our teachers."},{"title":"Apply","text":"Complete the application with previous school reports."},{"title":"Welcome","text":"Meet the principal and confirm your place."}],"button":{"label":"Contact admissions","href":"/contact"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":2,"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000}},"required":["title"],"additionalProperties":false}},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'faculty', 'Faculty cards', '{"eyebrow":"Leadership","title":"Meet our faculty","text":"Experienced, caring educators who bring every subject to life.","members":[{"name":"Mr. Daniel Brooks","subject":"Head of Sciences","image":{"src":"/themes/crestview/teacher-1.jpg","alt":"Daniel Brooks"}},{"name":"Ms. Priya Nair","subject":"English Literature","image":{"src":"/themes/crestview/teacher-2.jpg","alt":"Priya Nair"}},{"name":"Ms. Elena Ruiz","subject":"Mathematics","image":{"src":"/themes/crestview/teacher-3.jpg","alt":"Elena Ruiz"}},{"name":"Mr. Samuel Okafor","subject":"Athletics Director","image":{"src":"/themes/crestview/teacher-4.jpg","alt":"Samuel Okafor"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"subject":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 160);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'photo-points', 'Photo with points', '{"eyebrow":"Our mission","title":"Educating the whole child","text":"We combine academic excellence with care for character, wellbeing and community.","image":{"src":"/themes/crestview/classroom.jpg","alt":"Teacher presenting to a class"},"points":[{"title":"Academic excellence","text":"High standards and expert teaching in every subject.","icon":"award"},{"title":"Character and service","text":"Students lead, volunteer and learn to make a difference.","icon":"users"},{"title":"A safe, caring campus","text":"Wellbeing support and a culture of kindness and respect.","icon":"shield"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"icon":{"type":"string","enum":["graduation-cap","book","flask","calendar","trophy","palette","music","users","award","shield","landmark"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"imageRight":{"type":"string","enum":["yes","no"]}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 170);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'crestview' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Admissions FAQ","title":"Questions parents often ask","items":[{"question":"When do applications open?","answer":"Applications for the new academic year open in October and close at the end of January, subject to availability."},{"question":"Is there an entrance assessment?","answer":"Students from Grade 7 upwards take a short assessment in English and Mathematics, followed by a friendly conversation."},{"question":"Do you offer transport?","answer":"Yes. Our buses cover most parts of the city, with a trained attendant on every route."},{"question":"Are scholarships available?","answer":"We offer merit and need-based scholarships each year. Ask our admissions team for details."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'crestview';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'crestview' and c.slug in ('school', 'college', 'coaching-institute', 'online-education');
